def find_path(graph, start, goal):
    if start == goal:
        return [start]
    visited = set()
    priority_queue = [(0, start)]
    while priority_queue:
        cost, node = priority_queue.pop(0)
        if node in visited:
            continue
        visited.add(node)
        if node == goal:
            return [node] + visited
        for next_node in graph.get(node, []):
            priority_queue.append((cost + 1, next_node))
        priority_queue.sort(key=lambda x: (x[0] + (1 if next_node in visited else 0), next_node))
    return None
