        if node == goal:
            return True
        visited.add(node)
        for neighbor in graph[node]:
            if neighbor not in visited:
                if neighbor not in parents or dfs(parents[neighbor], goal, parents, visited):
                    parents[neighbor] = node
                    return True
        return False
    dfs(start, goal, parents, visited)
    if parents[goal] is None:
        return None
    path = [goal]
    while path[0] != start:
        goal = parents[path[0]]
        path.insert(0, goal)
    return path
